package com.catalogix.recommendation.config; import com.catalogix.recommendation.event.OrderConfirmedEvent; import com.catalogix.recommendation.service.RecommendationService; import org.springframework.amqp.rabbit.annotation.RabbitListener; import org.springframework.stereotype.Component; @Component public class OrderEventListener{final RecommendationService svc;public OrderEventListener(RecommendationService s){svc=s;}@RabbitListener(queues="recommendation.order-confirmed")public void on(OrderConfirmedEvent e){svc.ingest(e);}}
